   c('099', 'dir', 'Paulo viaja, planta igrejas e escreve cartas pra elas: Romanos, Coríntios, Gálatas, Efésios. É a promessa feita a Abraão se cumprindo: todas as famílias da terra sendo abençoadas.'),
   c('041', 'in', 'Última parada: Apocalipse. Não é um livro pra dar medo. É uma mensagem pra igrejas perseguidas: Jesus venceu, e ele vai voltar.', cap=dict(sup='PARADA 8', txt='O fim que é começo')),
   c('001', 'cima', 'E a Bíblia termina onde começou: num jardim. Novo céu e nova terra, Deus morando com o seu povo, sem morte, sem choro e sem dor.', verso='Eis que faço novas todas as coisas.', ref='APOCALIPSE 21.5'),
