   c('061', 'out', 'Lucas abre o livro dizendo que investigou tudo com cuidado e escreveu em ordem, pra um homem chamado Teófilo.', verso='Investiguei tudo cuidadosamente, desde o começo.', ref='LUCAS 1.3'),
