   c('001', 'esq', 'Repara como ele começa: não em Belém, mas antes de tudo. É um eco de Gênesis 1. Antes de nascer em Belém, Jesus já existia.', verso='No princípio era o Verbo, e o Verbo era Deus.', ref='JOÃO 1.1'),
   c('070', 'out', 'João organiza o livro em sinais: milagres que apontam pra quem Jesus é. A água virando vinho, o cego de nascença, a ressurreição de Lázaro.'),
   c('080', 'dir', 'E Jesus fala de si mesmo com frases que começam com Eu sou: eu sou o pão da vida, a luz do mundo, o bom pastor, a ressurreição e a vida, o caminho.'),
   c('077', 'in', 'João também tem conversas longas e pessoais. Nicodemos, de noite. A mulher samaritana, ao meio-dia, no poço.'),
   c('083', 'out', 'E ele dedica vários capítulos à última noite antes da cruz: Jesus lava os pés dos discípulos, consola, promete o Espírito Santo e ora por eles.'),
