   c('066', 'in', 'Uma dúvida comum: se os quatro contam a mesma história, por que tem detalhes diferentes? Um fala de um anjo no túmulo, outro fala de dois.', cap=dict(sup='PERGUNTA COMUM', txt='E as diferenças?')),
   c('092', 'esq', 'Pensa em testemunhas de um mesmo acontecimento. Cada uma destaca o que achou mais importante. Se todas contassem exatamente igual, palavra por palavra, aí sim seria estranho.'),
   c('049', 'out', 'Os quatro concordam no centro: Jesus ensinou, curou, foi crucificado e ressuscitou. As diferenças mostram ângulos, não histórias diferentes.'),
