def grava(arq, novos):
    f = f'{RAIZ}/{arq}'; d = json.load(open(f)); ids = {v['id'] for v in novos}
    d = [v for v in d if v['id'] not in ids] + novos; json.dump(d, open(f, 'w'), ensure_ascii=False, indent=1)
pint, sh, lg = [], [], []
for v in SHORTS:
    pint.append(dict(id=v['id'], formato='short', titulo=v['titulo'], legenda=v['legenda'], comentario=v['comentario'],
                     titulo_tela=dict(sup='PASSAPORTE DA BÍBLIA', txt=v['tela'], dur=2.4), cenas=v['cenas']))
    sh.append(dict(id=v['id'], formato='short', titulo=v['titulo'], legenda=v['legenda'], comentario=v['comentario'], capa=v['capa'], grav=v['grav']))
for v in LONGOS:
    pint.append(dict(id=v['id'], formato='longo', titulo=v['titulo'], legenda=v['legenda'], comentario=v['comentario'],
                     titulo_tela=dict(sup='PASSAPORTE DA BÍBLIA', txt=v['tela'], dur=3.2), cenas=v['cenas']))
    lg.append(dict(id=v['id'], titulo=v['titulo'], formato='longo', legenda=v['legenda'], comentario=v['comentario'], capaA=v['capaA'], capaB=v['capaB'], gravA=v['grav'][0], gravB=v['grav'][1]))
grava('pintura.json', pint); grava('shorts.json', sh); grava('longos.json', lg)
print(len(pint), 'roteiros;', sum(len(v['cenas']) for v in pint), 'cenas')
